def smallest_repeating_pattern(s):
    # Create a dictionary to track the last seen index of each character
    char_last_seen = {}

    # Iterate through the string with the character last seen index
    for i, char in enumerate(s):
        # If the character is already in the dictionary, update the last seen index
        if char in char_last_seen:
            char_last_seen[char] = i
        else:
            # If the character is not in the dictionary, start a new pattern
            if char not in char_last_seen:
                char_last_seen[char] = i
                i += 1  # Move to the next character to update the pattern length

    # Find the longest repeating pattern
    max_length = 0
    repeating_pattern = None

    # Iterate through the dictionary to find the longest repeating pattern
    for char, last_seen in char_last_seen.items():
        length = last_seen - char_last_seen.get(char, last_seen)
        if length > max_length:
            max_length = length
            repeating_pattern = char

    return repeating_pattern
