def min_path_sum(grid):
    # Initialize the dungeon with zeros
    dungeon = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            # If the current cell is not the starting cell (top-left corner)
            if i > 0 and j > 0:
                # Consider the minimum cost from the above or left cells
                dungeon[i][j] = min(dungeon[i-1][j], dungeon[i][j-1]) + grid[i][j]

    # The path with the minimum total cost is at the bottom-right corner
    return dungeon[len(grid)-1][len(grid[0])-1]
