def find_largest_binary_gap(N):
    bits = bin(N)[2:]  # Convert to binary string
    max_gap = 0
    current_gap = 0

    # Iterate through the string, count consecutive zeros
    for i in range(len(bits)):
        if bits[i] == '0':
            current_gap += 1
        else:
            if current_gap > max_gap:
                max_gap = current_gap
            current_gap = 0

    # Check the last gap
    if current_gap > max_gap:
        max_gap = current_gap

    return max_gap
