def is_anagram_of_palindrome(s: str) -> bool:
    # Normalize the string by removing spaces and converting to lowercase
    normalized_s = s.replace(" ", "").lower()

    # Count the frequency of each character in the normalized string
    char_count = {}
    for char in normalized_s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if the frequency of any character is odd
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string is an anagram of a palindrome if it has at most one odd count
    return odd_count <= 1
