def is_tree(edges: List[List[int]]) -> bool:
    """
    Determine if a given directed graph is a tree.

    Args:
    edges (List[List[int]]): A list of edges where each edge is represented as a tuple (node1, node2).

    Returns:
    bool: True if the graph is a tree, False otherwise.
    """
    if not edges or len(edges) < 2:
        return True

    visited = set()
    graph = {}

    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []

        graph[u].append(v)
        graph[v].append(u)

    root = list(graph.keys())[0]
    if root in visited:
        return False

    def dfs(node):
        nonlocal visited
        if node in visited:
            return False

        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if not dfs(neighbor):
                    return False
        visited.remove(node)
        return True

    return dfs(root)
