def median_of_two_sorted_arrays(arr1, arr2):
    n1, n2 = len(arr1), len(arr2)
    x = min(n1, n2)
    if n1 > n2:
        arr1, arr2 = arr2, arr1

    if x == 1:
        return arr1[0]

    i = 0
    j = n2 - 1
    k = (n1 + n2) // 2

    while i <= j:
        if i == j:
            return arr1[i]
        if k % 2 == 1:
            return min(arr1[i], arr2[j])
        mid = k // 2
        if arr1[mid] >= arr2[mid]:
            j = mid - 1
        else:
            i = mid + 1
