def median_of_two_sorted_arrays(arr1, arr2):
    # Helper function to find the median of two sorted arrays
    def find_median(arr1, arr2):
        # Return the average of the two sorted arrays
        return (arr1[-1] + arr2[-1]) / 2.0

    # Find the length of both arrays
    len1, len2 = len(arr1), len(arr2)

    # Determine the appropriate middle index
    mid1, mid2 = len1 // 2, len2 // 2

    # If the sum of the lengths of both arrays is odd, the median is the middle element
    if mid1 + mid2 == len1 + len2:
        return find_median(arr1, arr2)

    # If the sum of the lengths of both arrays is even, the median is the average of the two middle elements
    else:
        if len1 > len2:
            return find_median(arr1[:mid2], arr2[mid1:])
        else:
            return find_median(arr2[:mid1], arr1[mid2:])
