def longest_palindrome_subsequence(s):
    # Helper function to check if a substring is a palindrome
    def is_palindrome(sub):
        return sub == sub[::-1]

    # Function to find the longest palindromic subsequence
    def longest_palindrome(s, memo):
        if memo.get(s, -1) >= 0:
            return memo[s]

        # If the string is empty or has only one character, it's a palindrome
        if len(s) <= 1:
            return s

        # Iterate over all substrings of the given string
        max_length = 0
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                # Check if the substring from i to j is a palindrome
                if is_palindrome(s[i:j]):
                    # Update the maximum length found
                    max_length = max(max_length, len(s[i:j]))

        # Memoize the result
        memo[s] = max_length
        return max_length

    # Start the longest palindromic subsequence search
    return longest_palindrome(s, {})
