    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(i, n + 1):
            if s[i - 1] == s[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
