def find_largest_palindrome(orig: str) -> str:
    def is_palindrome(s):
        return s == s[::-1]

    def dfs(odd_idx, even_idx, palindromes, visited):
        if odd_idx == len(orig):
            palindromes.append(orig[odd_idx:])
            return

        if even_idx == len(orig):
            if is_palindrome(orig[odd_idx:]):
                palindromes.append(orig[odd_idx:])
            return

        if (odd_idx, even_idx) in visited:
            return

        visited.add((odd_idx, even_idx))

        dfs(odd_idx + 1, even_idx, palindromes, visited)
        dfs(odd_idx, even_idx + 2, palindromes, visited)

    visited = set()
    palindromes = []
    dfs(0, 0, palindromes, visited)
    return ''.join(palindromes[::-1])
