def minimum_deletion_cost(s1: str, s2: str) -> int:
    # Initialize a 2D matrix to store the minimum deletions for substrings
    dp = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]

    # Base case: A single character string can be deleted
    for i in range(len(s1) + 1):
        dp[i][0] = i

    # Filling the dp matrix
    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])

    # The minimum deletion cost to make two strings equal is stored in dp[len(s1)][len(s2)]
    return dp[len(s1)][len(s2)]
