def is_valid_bracket_sequence(s):
    """
    Determine if a given string is a valid bracket sequence.

    A valid bracket sequence consists of parentheses, square brackets, and curly braces
    that are correctly matched and nested.

    :param s: A string containing only the characters '(' ')' '[]' '{'
    :return: True if the string is a valid bracket sequence, False otherwise
    """
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        elif char == '[':
            balance += 1
        elif char == ']':
            balance -= 1
        elif char == '{':
            balance += 1
        elif char == '}':
            balance -= 1
        # If balance ever goes negative, there are more closing brackets than opening ones
        if balance < 0:
            return False
    # If balance is zero, all opening brackets have been matched
    return balance == 0

