def is_valid_bracket_sequence(s: str) -> bool:
    """
    Determines if a given string of brackets is valid.

    Args:
    s (str): A string consisting of parentheses, square brackets, and curly braces.

    Returns:
    bool: True if the string is a valid bracket sequence, False otherwise.
    """
    stack = []
    for char in s:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack:
                return False
            top = stack.pop()
            if top == '(' and char != ')':
                return False
            if top == '[' and char != ']':
                return False
            if top == '{' and char != '}':
                return False
    return not stack
