    # Helper function to count decode ways from single letter
    def count_decode(s):
        if len(s) == 1:
            return 1
        if len(s) == 2:
            return 2
        if s[1] == '0':
            return 0
        return count_decode(s[:-1]) + count_decode(s[-2:])

    # Helper function to count decode ways from two letter
    def count_decode_two(s):
        if len(s) < 2:
            return 0
        if s[0] == '0':
            return 0
        if s[1] == '0':
            return count_decode_two(s[2:])
        if int(s) > 26:
            return 0
        return count_decode_two(s[:-2]) + count_decode_two(s[-3:])

    return count_decode(s) + count_decode_two(s)
