def check_strictly_ascending(lst):
    """Check if a list of integers is in strictly ascending order and contains unique elements."""
    if len(lst) < 2:
        return True  # A list with 0 or 1 element is trivially sorted and has unique elements

    # Check if the list is strictly ascending
    for i in range(1, len(lst)):
        if lst[i] <= lst[i - 1]:
            return False

    # Check if the list contains unique elements
    seen = set()
    for num in lst:
        if num in seen:
            return False
        seen.add(num)

    return True
