def is_perfect(n):
    # Helper function to check if a number is prime
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Calculate the sum of proper divisors of n
    proper_sum = 0
    for i in range(1, n):
        if n % i == 0:
            proper_sum += i
            if is_prime(i) and i != n // i:
                proper_sum += n // i

    # Check if n is a perfect number
    return proper_sum == n

