def cut_rope(n):
    if n <= 1:
        return 0

    max_product = 0
    for i in range(1, n + 1):
        # If the current length is less than or equal to 1, it's a valid cut
        if i <= 1:
            max_product = max(max_product, i)

        # Calculate the product of all possible ways to split the rope into the current and next cut length
        for j in range(i + 1, n + 1):
            max_product = max(max_product, i * j)

    return max_product
