from math import comb

def coinChangeWays(coins, n):
    if n == 0:
        return 1
    if not coins:
        return 0

    # Find the highest power of each coin that is less than or equal to n
    power = []
    for coin in coins:
        power.append(int((n // coin) * coin))

    # Calculate the number of ways to make up n with the coins
    ways = [0] * (n + 1)
    ways[0] = 1

    for coin in power:
        for i in range(coin, n + 1):
            ways[i] += ways[i - coin]

    return ways[n]
