    def backtrack(path, remaining, candidates, target):
        if remaining == 0:
            result.append(path[:])
            return
        if target < 0:
            return
        for i in range(len(candidates)):
            if i > 0 and candidates[i] == candidates[i - 1]:
                continue
            backtrack(path + [candidates[i]], remaining - candidates[i], candidates[:i] + candidates[i + 1:], target)

    result = []
