    def backtrack(index, left, right):
        nonlocal valid
        if index == n:
            valid += 1
            return
        if left < n:
            backtrack(index + 1, left + 1, right)
        if right < left:
            backtrack(index + 1, left, right + 1)

    valid = 0
    backtrack(0, 0, 0)
    return valid
