def find_anagrams(words):
    # Helper function to sort a string alphabetically
    def sort_string(s):
        return ''.join(sorted(s))

    # Helper function to check if two strings are anagrams
    def are_anagrams(str1, str2):
        return sort_string(str1) == sort_string(str2)

    # List to hold anagrams
    anagrams = []

    # Iterate over each word in the input list
    for word in words:
        # Check if the word is already an anagram
        if are_anagrams(word, word):
            continue
        # Generate all possible anagrams of the current word
        for i in range(len(word)):
            for j in range(i + 1, len(word)):
                # Swap characters to form an anagram
                new_word = word[:i] + word[i + 1:j] + word[j:]
                # Add the anagram to the list
                anagrams.append((new_word, word))

    # Sort the anagrams first by the first element of each inner list
    anagrams.sort(key=lambda x: x[0])

    return anagrams
```

