        return sorted(str1) == sorted(str2)

    # Sort the list of words
    words.sort(key=lambda x: x)

    # Use a set to track anagrams
    anagram_set = set()

    for word in words:
        # Check if it is an anagram of the previous one
        if is_anagram(word, words[-2]) and word not in anagram_set:
            anagram_set.add(word)

    # Convert the set back to a list and return
    return list(anagram_set)

