def find_anagrams(words):
    def sort_string(s):
        return ''.join(sorted(s))

    def anagram_check(s1, s2):
        return sort_string(s1) == sort_string(s2)

    anagrams = []
    for word1 in words:
        for word2 in words:
            if anagram_check(word1, word2):
                anagrams.append([sort_string(word1), sort_string(word2)])

    anagrams.sort(key=lambda x: (x[0], x[1]))

    return anagrams
```

