def fibonacci(n):
    # Base case: the first and second Fibonacci numbers are 0 and 1 respectively
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        # Recursive case: the nth Fibonacci number is the sum of the (n-1) and (n-2) Fibonacci numbers
        return fibonacci(n-1) + fibonacci(n-2)
