    # Check if num is zero and zero raised to any power is zero
    if num == 0 and 1 < num:
        return True
    # Check if the absolute value of num is less than 3
    if abs(num) < 3:
        return False
    # Check if num is a power of three
    while num > 3:
        if num % 3 != 0:
            return False
        num //= 3
    return True
