def is_valid_ip(ip: str) -> bool:
    # Split the string by dots to get octets
    octets = ip.split('.')

    # Check if the number of octets is 4
    if len(octets) != 4:
        return False

    # Attempt to convert each octet to an integer
    for octet in octets:
        try:
            # Convert octet to an integer
            int_octet = int(octet)
            # Check if the integer is within the valid range
            if int_octet < 0 or int_octet > 255:
                return False
        except ValueError:
            return False

    # If all octets are valid, return True
    return True
