def binary_gap(N):
    # Convert N to binary and split into individual bits
    bits = bin(N)[2:]
    # Find the index of the first zero on the right
    right_zero = bits.find('1', 1)

    # Find the index of the first one on the left
    left_one = bits.find('0', 0)

    # Calculate the length of the longest gap
    # If right_zero is greater than left_one, the gap is from the right
    if right_zero > left_one:
        return len(bits) - (right_zero + 1)
    else:
        return len(bits) - (left_one + 1)
