    if n1 == 0 or n2 == 0:
        return 0

    dp = [[0] * (n2 + 1) for _ in range(n1 + 1)]

    for i in range(1, n1 + 1):
        for j in range(1, n2 + 1):
            if main_str[i - 1] == target_str[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
