from collections import *

def count_subsequences(main_str: str, target_str: str) -> int:
    if not target_str or not main_str:
        return 0

    n, m = len(main_str), len(target_str)
    dp = [[0] * (m+1) for _ in range(n+1)]

    # Base case: subsequences of length 1 are always 1, as they are the same
    for i in range(n+1):
        dp[i][1] = 1

    # Fill the DP table
    for i in range(2, n+1):
        for j in range(2, m+1):
            if main_str[i-1] == target_str[j-1]:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j]

    return dp[n][m]
