class Solution:
    def max_nested_parentheses(self, s: str) -> int:
        stack = []
        max_depth = 0

        for char in s:
            if char == '(':
                stack.append(char)
                max_depth = max(max_depth, len(stack))
            elif char == ')':
                if stack:
                    stack.pop()
                else:
                    # This line should never be reached since we've a matching opening parenthesis
                    raise ValueError("Unbalanced parentheses")

        return max_depth
