def remove_smallest(numbers):
    # Check if the list is empty or has only one element
    if len(numbers) <= 1:
        return numbers.copy()

    # Initialize variables to track the smallest number and its count
    smallest = numbers[0]
    count = 1

    # Iterate through the list to find the smallest number and its count
    for num in numbers:
        if num < smallest:
            smallest = num
            count = 1
        elif num == smallest:
            count += 1

    # If there is more than one occurrence of the smallest number, remove the last occurrence
    if count > 1:
        numbers.remove(smallest)

    return numbers
