def decode_message(s: str) -> int:
    if not s or s == "0":  # No valid decoding
        return 0

    # Convert the string into a list of characters
    digits = list(s)

    @lru_cache(maxsize=None)
    def dp(i):
        if i == len(digits):
            return 1
        if i == len(digits) - 1:
            return 0 if digits[i] == "0" else 1

        # Check if the current character can be followed by a digit
        if digits[i + 1] != "0" and int(digits[i:i+2]) <= 26:
            return dp(i + 2)

        # Consider both possibilities
        return dp(i + 1) + dp(i + 2)

    return dp(0)
