def binary_gap(N):
    # Initialize variables to keep track of the largest gap
    longest_gap = 0
    current_gap = 0
    # Flag to check if we are currently in a gap
    in_gap = False

    # Iterate through each bit of N
    for bit in bin(N)[2:]:
        # If the bit is a '1', start a new gap
        if bit == '1':
            if current_gap == 0:
                in_gap = True
            else:
                # Calculate the gap and update longest gap if necessary
                current_gap = bit - current_gap
                if current_gap > longest_gap:
                    longest_gap = current_gap
        else:
            # Reset the current gap if the bit is '0'
            current_gap = 0

    return longest_gap
