def check_pattern(pattern: str, s: str) -> bool:
    if len(pattern) != len(s):
        return False

    # Dictionary to store the mapping between characters in pattern and words in string
    mapping = {}

    # Iterate over each character in the pattern
    for i, char in enumerate(pattern):
        # Find the word in string that maps to the current character in pattern
        word = [s[i+j:i+j+len(word)] for j in range(len(word))]

        # Check if the word exists in the dictionary
        if word not in mapping:
            # If not, add the word to the dictionary with the original character as the key
            mapping[word] = char

    # Check if all characters in pattern have been mapped to words in string
    return all([char in mapping for char in pattern])

