        return 0
    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            if divisor not in factors:
                factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return len(factors)
