def valid_parentheses_sequence(s: str) -> bool:
    """
    Check if a string is a valid parentheses sequence.

    A valid parentheses sequence is one where every opening parenthesis ('(', '[', or '{') is properly closed by its corresponding closing parenthesis (')', ']', or '}').

    :param s: The string to check.
    :return: True if the string is a valid parentheses sequence, False otherwise.
    """
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == '[':
            balance += 1
        elif char == '{':
            balance += 1
        elif char == ')':
            balance -= 1
        elif char == ']':
            balance -= 1
        elif char == '}':
            balance -= 1
        # If balance goes negative, it means there is a closing parenthesis before an opening one
        if balance < 0:
            return False
    # If balance is zero, all opening parentheses had matching closing ones
    return balance == 0
