def find_repeating_pattern(s: str) -> tuple:
    # Check if the string is empty or has one character
    if len(s) <= 1 or len(set(s)) != 1:
        return s, 1

    # Create a set of unique characters in the string
    unique_chars = set(s)

    # Try all possible substrings of length equal to the number of unique characters in the string
    for n in range(1, len(unique_chars) + 1):
        for i in range(len(s) - n + 1):
            pattern = s[i:i+n]
            # Check if all characters in the pattern match the unique characters in the string
            if all(c in unique_chars for c in pattern):
                # Check if the pattern repeats
                if s[:i] == s[i+i:n] and s[i] == pattern[0]:
                    # Return the pattern and the number of times it repeats
                    return pattern, n
    # If no repeating pattern is found, return the string itself and a repetition count of 1
    return s, 1
