def isPermutation(str1, str2):
    # Create a frequency map for the first string
    freq_map1 = {}
    for char in str1:
        if char in freq_map1:
            freq_map1[char] += 1
        else:
            freq_map1[char] = 1

    # Create a frequency map for the second string
    freq_map2 = {}
    for char in str2:
        if char in freq_map2:
            freq_map2[char] += 1
        else:
            freq_map2[char] = 1

    # Compare the frequency maps
    return freq_map1 == freq_map2

# Example usage:
