def most_common(lst):
    # Calculate the frequency of each element in the list
    frequency = {}
    for elem in lst:
        if elem in frequency:
            frequency[elem] += 1
        else:
            frequency[elem] = 1

    # Find the maximum frequency
    max_frequency = max(frequency.values())

    # Collect elements with the maximum frequency
    most_common_elements = [elem for elem, freq in frequency.items() if freq == max_frequency]

    # Return the result in the order they appear in the original list
    return most_common_elements
