def has_dominant_number(A):
    # Create a dictionary to count the frequency of each number
    frequency = {}
    for num in A:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Determine the median of the frequency dictionary
    sorted_frequency = sorted(frequency.values())
    n = len(sorted_frequency)

    # The median is the middle element in the sorted list
    if n % 2 == 0:
        return sorted_frequency[n // 2]
    else:
        return sorted_frequency[n // 2 - 1]
