def has_dominant_number(A):
    # Helper function to count occurrences of a number in the sequence
    def count_occurrences(num, A):
        count = 0
        for item in A:
            if item == num:
                count += 1
        return count

    # Count occurrences of each number in the sequence
    occurrences = [count_occurrences(num, A) for num in A]

    # Determine if any number has more than half the count
    for count in occurrences:
        if count > len(A) / 2:
            return True

    return False

