def num_ways_to_roll_dice(d: int, f: int, target: int) -> int:
    # Helper function to generate all possible combinations of dice rolls and their sums
    def generate_combinations(dice_faces: int, target: int, current_sum: int, remaining_dice: int, modulo: int) -> int:
        if current_sum == target:
            return 1
        if remaining_dice == 0:
            return 0

        total_ways = 0
        for i in range(min(dice_faces, remaining_dice) + 1):
            new_current_sum = current_sum + i
            new_remaining_dice = remaining_dice - i
            new_modulo = (new_current_sum % modulo) if new_current_sum % modulo != 0 else modulo
            total_ways += generate_combinations(dice_faces, target, new_current_sum, new_remaining_dice, new_modulo)

        return total_ways

    # Calculate the number of ways to roll the given number of dice
    return generate_combinations(d, target, 0, d, 10**9 + 7)
