def num_ways_to_roll_dice(d: int, f: int, target: int) -> int:
    import math
    mod = 10**9 + 7
    result = 0
    for i in range(1, min(d, f) + 1):
        count = math.comb(f, i) * math.comb(d - i, f - i)
        if count >= target:
            result += count % mod
        else:
            break
    return result % mod
