def is_valid_shuffle(str1, str2, shuffle):
    """Check if str1 and str2 can be shuffled to form shuffle as a substring."""
    # Check if the length of str1 and str2 is greater than shuffle
    if len(str1) > len(shuffle):
        return False

    # Iterate through shuffle and check if it can be interleaved with str1 and str2
    for i in range(len(shuffle)):
        # Check if the current character in shuffle is present in str1
        if shuffle[i] in str1:
            # Check if the current character in shuffle is present in str2
            if shuffle[i] in str2:
                # If both characters are present, check if they match
                if str1[i:i+len(shuffle) % len(str1)] == str2[i:i+len(shuffle) % len(str2)]:
                    continue
                else:
                    return False
            else:
                return False
        else:
            return False

    # If all characters in shuffle are present in both str1 and str2, return True
    return True
