    # Check lengths of the strings
    if len(str1) + len(str2) != len(shuffle):
        return False

    # Dictionary to count character occurrences in each string
    count1 = {}
    count2 = {}

    # Count characters in each string
    for char in str1:
        count1[char] = count1.get(char, 0) + 1
    for char in str2:
        count2[char] = count2.get(char, 0) + 1

    # Check if each character in shuffle can be formed with characters from both strings
    for char in shuffle:
        if char not in count1 or char not in count2:
            return False
        count1[char] -= 1
        count2[char] -= 1

        # If all characters are used up, the current shuffle is valid
        if all(count1[char] == 0 and count2[char] == 0 for char in shuffle):
            return True

