class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def num_unique_bst(n):
    """
    Calculate the number of unique binary search trees (BSTs) with values 1 to n.
    A unique BST is defined as a binary search tree that is not identical to any other binary search tree with the same values.

    Parameters:
    n (int): The number of nodes in the tree.

    Returns:
    int: The number of unique BSTs.
    """
    if n == 0:
        return 1
    unique_trees = []
    for i in range(1, n + 1):
        for j in range(i):
            left_subtree = num_unique_bst(j)
            right_subtree = num_unique_bst(n - i - 1)
            for tree in left_subtree:
                for tree in right_subtree:
                    unique_trees.append(TreeNode(i, tree, tree))
    return len(unique_trees)
