def smallest_subsequence(s: str) -> str:
    # Create a dictionary to count occurrences of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # List characters with counts greater than 1
    to_remove = [char for char, count in char_count.items() if count > 1]

    # Sort characters in descending order based on their count
    sorted_chars = sorted(to_remove, key=lambda char: char_count[char], reverse=True)

    # Construct the smallest subsequence
    result = []
    for char in sorted_chars:
        while char_count[char] > 0:
            result.append(char)
            char_count[char] -= 1

    return ''.join(result)
```

