    Find the nth term of the Look-and-Say sequence.

    :param n: The position in the Look-and-Say sequence to find.
    :return: The nth term of the Look-and-Say sequence.
    """
    if n <= 1:
        return str(n)

    def next_term(s):
        count = 1
        result = []
        for char in s:
            if char == s[-1]:
                count += 1
            else:
                result.append(str(count))
                count = 1
        result.append(str(count))
        return ''.join(result)

    return next_term(look_and_say(n - 1))
