def max_length_subarray_sum(arr, k):
    if not arr or not k:
        return 0

    n = len(arr)
    max_length = 0
    current_sum = 0

    for i in range(n):
        current_sum += arr[i]

        if current_sum == k:
            max_length = max(max_length, i + 1)
        elif current_sum - k in [0, -1]:
            max_length = max(max_length, i - current_sum)

